<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('credit.record_payment');$customerId=(int)($_GET['customer']??0);$st=db()->prepare('SELECT * FROM customers WHERE id=:id AND status="active"');$st->execute([':id'=>$customerId]);$customer=$st->fetch();if(!$customer){flash('error','Customer not found.');redirect('credit/debts');}$methods=db()->query('SELECT id,name,method_type,requires_reference FROM payment_methods WHERE is_active=1 AND method_type<>"credit" ORDER BY sort_order,name')->fetchAll();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$methodId=(int)($_POST['payment_method_id']??0);$reference=trim((string)($_POST['reference_no']??''));$notes=trim((string)($_POST['notes']??''));try{$amount=money_to_cents((string)($_POST['amount']??'0'));$balance=money_to_cents($customer['account_balance']);if($amount<=0||$amount>$balance)throw new RuntimeException('Payment must be greater than zero and not exceed the outstanding balance.');}catch(Throwable$e){$errors[]=$e->getMessage()?:'Enter a valid payment amount.';$amount=0;}$method=payment_method_by_id(db(),$methodId);if(!$method||$method['method_type']==='credit')$errors[]='Choose a valid payment method.';
if(!$errors){$pdo=db();try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT account_balance FROM customers WHERE id=:id FOR UPDATE');$lock->execute([':id'=>$customerId]);$freshBalance=money_to_cents((string)$lock->fetchColumn());if($amount>$freshBalance)throw new RuntimeException('Payment exceeds the current customer balance.');$paymentNo=next_document_number($pdo,'customer_payment');$cp=$pdo->prepare('INSERT INTO customer_payments(customer_id,payment_no,payment_method_id,amount,reference_no,payment_date,notes,received_by) VALUES(:customer,:no,:method,:amount,:ref,NOW(),:notes,:user)');$cp->execute([':customer'=>$customerId,':no'=>$paymentNo,':method'=>$methodId,':amount'=>cents_to_decimal($amount),':ref'=>$reference?:null,':notes'=>$notes?:null,':user'=>(int)current_user()['id']]);$paymentId=(int)$pdo->lastInsertId();
$remaining=$amount;$sales=$pdo->prepare('SELECT id,balance_due,amount_paid FROM sales WHERE customer_id=:customer AND status="completed" AND balance_due>0 ORDER BY sale_date,id FOR UPDATE');$sales->execute([':customer'=>$customerId]);foreach($sales->fetchAll() as$sale){if($remaining<=0)break;$saleBalance=money_to_cents($sale['balance_due']);$allocation=min($remaining,$saleBalance);if($allocation<=0)continue;$alloc=$pdo->prepare('INSERT INTO customer_payment_allocations(customer_payment_id,sale_id,amount) VALUES(:payment,:sale,:amount)');$alloc->execute([':payment'=>$paymentId,':sale'=>(int)$sale['id'],':amount'=>cents_to_decimal($allocation)]);$newSaleBalance=$saleBalance-$allocation;$newSalePaid=money_to_cents($sale['amount_paid'])+$allocation;$saleStatus=$newSaleBalance===0?'paid':'partial';$su=$pdo->prepare('UPDATE sales SET amount_paid=:paid,balance_due=:balance,payment_status=:status WHERE id=:id');$su->execute([':paid'=>cents_to_decimal($newSalePaid),':balance'=>cents_to_decimal($newSaleBalance),':status'=>$saleStatus,':id'=>(int)$sale['id']]);$remaining-=$allocation;}
$newCustomerBalance=$freshBalance-$amount;$cu=$pdo->prepare('UPDATE customers SET account_balance=:balance WHERE id=:id');$cu->execute([':balance'=>cents_to_decimal($newCustomerBalance),':id'=>$customerId]);$ledger=$pdo->prepare('INSERT INTO customer_ledger(customer_id,entry_date,entry_type,customer_payment_id,reference_no,description,debit_amount,credit_amount,balance_after,created_by) VALUES(:customer,NOW(),"payment",:payment,:ref,:description,0.00,:amount,:balance,:user)');$ledger->execute([':customer'=>$customerId,':payment'=>$paymentId,':ref'=>$paymentNo,':description'=>'Customer debt payment',':amount'=>cents_to_decimal($amount),':balance'=>cents_to_decimal($newCustomerBalance),':user'=>(int)current_user()['id']]);if($method['method_type']==='cash'){$cm=$pdo->prepare('INSERT INTO cash_movements(cash_session_id,branch_id,movement_type,reference_type,reference_id,amount,description,created_by) VALUES(:session,:branch,"customer_payment","customer_payment",:id,:amount,:description,:user)');$cm->execute([':session'=>active_cash_session_id($pdo,(int)current_user()['id'],current_branch_id()),':branch'=>current_branch_id(),':id'=>$paymentId,':amount'=>cents_to_decimal($amount),':description'=>'Customer payment '.$paymentNo,':user'=>(int)current_user()['id']]);}$pdo->commit();audit_log('customer_payment_recorded','credit',$paymentId,'Customer payment recorded: '.$paymentNo.'.',null,['customer_id'=>$customerId,'amount'=>cents_to_decimal($amount),'method'=>$method['name']]);flash('success','Payment '.$paymentNo.' recorded successfully.');redirect('customers/view?id='.$customerId);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();error_log('Customer payment failed: '.$e->getMessage());$errors[]='The payment could not be recorded.';}}}
$pageTitle='Record Customer Payment';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="narrow-page"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('customers/view?id='.$customerId))?>">← <?=e($customer['name'])?></a><h2>Record debt payment</h2><p>Outstanding balance <?=e(money($customer['account_balance']))?></p></div></div><?php foreach($errors as$er):?><div class="app-alert app-alert--danger"><?=e($er)?></div><?php endforeach;?><form method="post" class="form-card"><?=csrf_field()?><div class="form-section"><div class="form-grid"><div class="field field--span-2"><label>Amount received</label><input type="number" name="amount" min="0.01" max="<?=e($customer['account_balance'])?>" step="0.01" value="<?=e($customer['account_balance'])?>" required></div><div class="field"><label>Payment method</label><select name="payment_method_id" required><option value="">Select method</option><?php foreach($methods as$m):?><option value="<?=e((string)$m['id'])?>"><?=e($m['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Reference</label><input name="reference_no" maxlength="120"></div><div class="field field--span-2"><label>Notes</label><textarea name="notes" rows="3"></textarea></div></div></div><div class="form-actions"><a class="button button--ghost" href="<?=e(app_url('customers/view?id='.$customerId))?>">Cancel</a><button class="button button--primary">Record payment</button></div></form></div></main></div><?php require BASE_PATH.'/includes/footer.php';?>
